prompt:
Review this Go payment change for financial correctness. Report only must-fix findings, each with a reachable failure schedule and the repair invariant; do not implement the change.

type Request struct { PaymentID string; Amount int64; Currency string }

func (s *Service) Authorize(ctx context.Context, req Request) (Authorization, error) {
    providerKey := fmt.Sprintf("%s-%d", req.PaymentID, time.Now().UnixNano())
    authorization, err := s.provider.Authorize(ctx, providerKey, req.Amount, req.Currency)
    if errors.Is(err, context.DeadlineExceeded) {
        _ = s.db.SaveAttempt(ctx, Attempt{PaymentID: req.PaymentID, ProviderKey: providerKey, Status: "declined"})
        return Authorization{}, ErrDeclined
    }
    if err != nil { return Authorization{}, err }
    if err := s.db.SaveAttempt(ctx, Attempt{PaymentID: req.PaymentID, ProviderKey: providerKey, ProviderID: authorization.ID, Status: "authorized"}); err != nil {
        return Authorization{}, err
    }
    return authorization, nil
}

func (s *Service) Retry(ctx context.Context, req Request) (Authorization, error) {
    return s.Authorize(ctx, req)
}

func (s *Service) ApplyWebhook(ctx context.Context, event Webhook) error {
    attempt, err := s.db.LatestByPaymentID(ctx, event.PaymentID)
    if err != nil { return err }
    return s.db.SetStatus(ctx, attempt.ID, event.Status)
}
